     * Limit[1000[INTEGER]]
     * \_EsqlProject[[s{r}#3, s_expr{r}#5, s_null{r}#7, w{r}#10]]
     *   \_Project[[s{r}#3, s_expr{r}#5, s_null{r}#7, w{r}#10]]
